/// Epistemic certainty floor across supporting events in a cell. Append new values only.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
#[repr(transparent)]
pub struct tmxCertaintyLevel(pub i8);

#[allow(non_upper_case_globals)]
impl tmxCertaintyLevel {
    /// Not stated.
    pub const UNSPECIFIED: Self = Self(0);
    /// Directly measured.
    pub const MEASURED: Self = Self(1);
    /// Authoritative published data.
    pub const PUBLISHED: Self = Self(2);
    /// Derived from kinematic bounds.
    pub const KINEMATIC_BOUND: Self = Self(3);
    /// Analyst-stated what-if override.
    pub const STATED_WHATIF: Self = Self(4);
    /// Redacted or restricted; not public.
    pub const NOT_PUBLIC: Self = Self(5);

    pub const ENUM_MIN: i8 = 0;
    pub const ENUM_MAX: i8 = 5;
    pub const ENUM_VALUES: &'static [Self] = &[
        Self::UNSPECIFIED,
        Self::MEASURED,
        Self::PUBLISHED,
        Self::KINEMATIC_BOUND,
        Self::STATED_WHATIF,
        Self::NOT_PUBLIC,
    ];

    /// Returns the variant's name or "" if unknown.
    pub fn variant_name(self) -> Option<&'static str> {
        match self {
            Self::UNSPECIFIED => Some("UNSPECIFIED"),
            Self::MEASURED => Some("MEASURED"),
            Self::PUBLISHED => Some("PUBLISHED"),
            Self::KINEMATIC_BOUND => Some("KINEMATIC_BOUND"),
            Self::STATED_WHATIF => Some("STATED_WHATIF"),
            Self::NOT_PUBLIC => Some("NOT_PUBLIC"),
            _ => None,
        }
    }
}

