        builder.add_NORAD_CAT_ID(args.NORAD_CAT_ID);
        if let Some(x) = args.BUCKET_ID { builder.add_BUCKET_ID(x); }
        if let Some(x) = args.COMPOUND_ID { builder.add_COMPOUND_ID(x); }
        builder.add_COMBINED_SCORE(args.COMBINED_SCORE);
        builder.add_COMPOUND_BONUS_BPS(args.COMPOUND_BONUS_BPS);
        builder.add_COMPOUND_MULTIPLIER_BPS(args.COMPOUND_MULTIPLIER_BPS);
        builder.add_SEVERITY_TIER(args.SEVERITY_TIER);
